package bookstore

import "sort"

// Cost returns the total price (in cents) of the books in the basket,
// applying the largest possible discount.
//
// Books are grouped into sets of distinct titles. A set of k distinct books
// gets a discount of [0, 5, 10, 20, 25]% for k = [1, 2, 3, 4, 5], so each
// book in such a set costs perBook[k] cents.
//
// The only non-trivial tradeoff: a group of five plus a group of three costs
// 5*600 + 3*720 = 5160, while two groups of four cost 2*4*640 = 5120. So when
// forming a five-group would leave exactly three distinct books for the next
// group, we instead form a four-group.
func Cost(books []int) int {
	// perBook[k] = price of one book inside a group of k distinct books.
	perBook := [5]int{800, 760, 720, 640, 600}

	// counts[i] = number of copies of book i+1.
	counts := [5]int{}
	for _, b := range books {
		counts[b-1]++
	}

	c := counts[:]
	sort.IntSlice(c).Sort() // ascending: c[0] <= c[1] <= ... <= c[4]

	cost := 0
	for {
		// k = number of distinct books still available.
		k := 0
		for k < 5 && c[k] > 0 {
			k++
		}
		if k == 0 {
			break
		}

		size := k
		if k == 5 {
			// Books left over after taking a five-group.
			next := 0
			for j := 0; j < 5; j++ {
				if c[j] >= 2 {
					next++
				}
			}
			// Avoid a five-group followed by a three-group.
			if next == 3 {
				size = 4
			}
		}

		cost += size * perBook[size]

		// Use one copy of the `size` most abundant books.
		for j := 5 - size; j < 5; j++ {
			c[j]--
		}
		sort.IntSlice(c).Sort()
	}

	return cost
}

